INSERT INTO recipes (id, name, ingredients, instructions, tags, serves) VALUES
(141, 'Ten-garlic-clove focaccia', '[{"section_title":"Main","items":[{"name":"strong white bread flour","quantity":"550g","unit":"","notes":"plus extra for dusting"},{"name":"instant yeast","quantity":"2","unit":"tsp (1 x 7g sachet)"},{"name":"Fine sea salt","quantity":"1 1/2","unit":"tsp"},{"name":"garlic cloves","quantity":"10","unit":"","notes":"peeled and crushed"},{"name":"extra-virgin olive oil","quantity":"8","unit":"tbsp (120ml)","notes":"plus extra for greasing and more to finish"},{"name":"lemon juice","quantity":"1 1/2","unit":"tbsp"},{"name":"polenta or cornmeal","quantity":"1","unit":"small handful"},{"name":"finely chopped flat-leaf parsley","quantity":"5-6","unit":"tbsp (20g)"},{"name":"Coarse sea salt","quantity":"","unit":""}]}]', '["Clean and dry a work surface, then dust it with flour. Put the flour, yeast and a teaspoon and a half of salt in a large bowl and whisk to combine.","Put 400ml warm water in a jug, and pour it into the bowl, mixing as you go, until you have a sticky dough.","Turn out the dough on to the surface, then scrape the bowl clean. Stretch and fold the dough for about five minutes, until it is smooth and springy.","Lightly oil the bowl, put the dough inside smooth side up, cover with a clean tea towel and leave to (roughly) double in size - this could take up to an hour.","Meanwhile, make the garlic oil. Put the crushed garlic and oil in a small saucepan and bring to a boil over a low to medium heat. Leave to bubble for two minutes, then take off the heat and set aside to cool. Once cool, add the lemon juice and half a teaspoon of fine sea salt.","Heat the oven to 240C (220C fan)/gas 9. Grease the tin with oil, and scatter over the polenta (this will help stop the bread sticking).","Gently lift the dough from its bowl (don''t worry if it deflates), and push into the tray, spreading it evenly. Cover with a tea towel and leave to prove again for another 45 minutes.","Push fingers all over the dough, to make holes, then spread two tablespoons of the garlic oil (but not the garlic itself) over the top.","Bake for 30 minutes, until golden, then remove from the oven. Mix the parsley into the remaining garlic oil mixture, then pour over the bread. If you like your focaccia generously oiled, as I do, add an extra drizzle of olive oil. Sprinkle over a little sea salt, and eat while warm."]', 'Focaccia, Bread, Vegan', '6-8'),
(142, 'batata harra: middle eastern skillet potatoes', '[{"section_title":"Main","items":[{"name":"medium-sized gold potatoes","quantity":"6","unit":"","notes":"peeled"},{"name":"Water","quantity":"","unit":""},{"name":"extra virgin olive oil","quantity":"3","unit":"tbsp"},{"name":"garlic cloves","quantity":"2","unit":"","notes":"minced"},{"name":"coriander seeds","quantity":"2","unit":"tsp","notes":"or 1 tsp ground"},{"name":"crushed red pepper flakes","quantity":"1","unit":"tsp","notes":"more for later"},{"name":"ground turmeric","quantity":"2","unit":"tsp"},{"name":"lime","quantity":"1","unit":"juice of"},{"name":"chopped fresh cilantro leaves","quantity":"1","unit":"cup"},{"name":"chopped fresh parsley leaves","quantity":"1","unit":"cup"},{"name":"chopped fresh dill","quantity":"1","unit":"cup"},{"name":"Salt and pepper","quantity":"","unit":""}]}]', '["Peel the potatoes and place them in a large pot with enough water to cover them. Bring to a boil, and let them cook in the boiling water for 10 minutes or so. The potatoes should be cooked through but still firm.","Drain the potatoes and let them cool briefly. Cut the potatoes in smaller bite-size cubes or pieces.","Heat the olive oil in a cast-iron skillet on medium. Stir in the garlic, red pepper flakes and coriander seeds. Cook for 2-3 minutes then add the turmeric and the lime juice.","Toss in the potatoes, and mix well to coat. Add 1/2 of the fresh cilantro, parsley and fresh dill. Cook for 4 more minutes. Add salt and black pepper to your taste.","Remove from heat and top with more red pepper flakes and the remaining fresh herbs. You can serve this potato salad warm or at room temperature."]', 'Potato, Side, Middle Eastern, Vegan, Gluten-free', '4'),
(143, 'Spaghetti with red wine and onion', '[{"section_title":"Main","items":[{"name":"large white onion","quantity":"1","unit":"","notes":"or red onion / bunch of spring onions (bulbs and pale parts)"},{"name":"butter","quantity":"20g","unit":""},{"name":"olive oil","quantity":"3","unit":"tbsp"},{"name":"red wine","quantity":"300ml","unit":""},{"name":"pasta (e.g., spaghetti)","quantity":"450g","unit":""},{"name":"grated parmesan","quantity":"2","unit":"tbsp","notes":"plus more to serve"},{"name":"salt","quantity":"1","unit":"pinch"},{"name":"black pepper","quantity":"","unit":""}]}]', '["Slice the onion into half-moons.","In a large frying pan with a lid set over a medium-low heat, melt the butter and olive oil. Add the onion and a pinch of salt, stir, then cover the pan and leave to cook down gently for about 10 minutes.","Once the onion is soft, add 300ml red wine and leave it to simmer uncovered for about 25 minutes, until the wine has reduced and the onion is collapsed and creamy. If at any point the mix seems at all dry, add a little more wine, or some warm water.","While the sauce simmers, cook 450g pasta until al dente.","Lift the pasta directly into the now purple onions and toss energetically.","Add two tablespoons of grated parmesan, some black pepper and a little of the pasta cooking water, if it needs it, then toss again.","Serve, passing round more grated parmesan for those who want it."]', 'Pasta, Vegetarian', '4'),
(144, 'Macaroni Cheese', '[{"section_title":"Main","items":[{"name":"short cut macaroni","quantity":"225g","unit":""},{"name":"butter or margarine","quantity":"65g","unit":""},{"name":"flour","quantity":"60ml","unit":"(4 level tbsp)"},{"name":"milk","quantity":"900ml","unit":"(1 1/2 pints)"},{"name":"salt and pepper","quantity":"","unit":""},{"name":"freshly grated nutmeg","quantity":"1","unit":"pinch","notes":"or 1/2 level tsp prepared mustard"},{"name":"mature Cheddar cheese","quantity":"225g","unit":"grated"},{"name":"fresh breadcrumbs","quantity":"45ml","unit":"(3 level tbsp)"}]}]', '["Cook the macaroni in a large saucepan of fast-boiling salted water for about 10 minutes for dried pasta or 3 minutes for fresh pasta until just tender and drain well. Keep warm.","Meanwhile, melt the butter in a saucepan, stir in the flour and cook gently for 1 minute.","Remove pan from the heat and gradually stir in the milk. Bring to the boil and continue to cook, stirring, until the sauce thickens.","Remove from the heat and add seasoning, nutmeg or mustard, 175g (6 oz) cheese and the macaroni.","Pour into an ovenproof dish and sprinkle with the remaining cheese and breadcrumbs.","Place on a baking sheet and bake in the oven at 200°C (400°F) mark 6 for about 20 minutes, until golden and bubbling, or brown under a very hot grill."]', 'Pasta, Vegetarian, Macaroni Cheese', '4 as a snack'),
(145, 'Lentil and roast vegetable salad', '[{"section_title":"Main","items":[{"name":"aubergine","quantity":"1","unit":""},{"name":"red peppers","quantity":"3","unit":""},{"name":"banana shallots","quantity":"8","unit":""},{"name":"garlic cloves","quantity":"4","unit":"","notes":"unpeeled"},{"name":"olive oil","quantity":"7","unit":"tbsp"},{"name":"dried marjoram","quantity":"1","unit":"tsp"},{"name":"dried oregano","quantity":"1","unit":"tsp"},{"name":"salt","quantity":"1 1/2","unit":"tsp"},{"name":"lemon","quantity":"1","unit":"juiced"},{"name":"chilli flakes","quantity":"1","unit":"tsp"},{"name":"frozen peas","quantity":"150g","unit":"defrosted"},{"name":"pre-cooked puy lentils","quantity":"2 x 250g","unit":"packs"}]}]', '["Heat the oven to 180C (160C fan)/gas 4. Chop the aubergine and peppers into roughly 2cm x 4cm, bite-sized chunks, then put in a large bowl.","Top and tail the shallots, take off and discard the skins, then quarter them and add to the bowl.","Roughly crush the whole, unpeeled garlic cloves with the back of a knife, and add to the bowl with four tablespoons of the oil, the marjoram, oregano and a teaspoon of salt. Mix everything with your hands until all the vegetables are coated in herby oil.","Tip out on to two roasting trays (don''t wash up the bowl). Gently pat down the vegetables, so they sit in one even layer, then roast for 40 minutes, stirring once halfway through.","While the vegetables are cooking, make the dressing. Pour the remaining three tablespoons of oil into the salad bowl, add the lemon juice and chilli flakes, and mix well.","Lift the garlic cloves from the roast vegetable trays, squeeze out the flesh on to a board, then roughly chop and stir into the dressing. Add the peas to the salad bowl, and toss to mix.","If you''d prefer to eat the salad warm, heat the lentils according to the instructions, otherwise just tip them straight from the packet into the salad bowl, add the roast vegetables and remaining half-teaspoon of salt, toss and serve."]', 'Salad, Vegetarian, Vegan, Lentil, Roast', '4 as a light meal'),
(146, 'Roast Vegetable and Cashew Pie', '[{"section_title":"Filling","items":[{"name":"small to medium aubergines","quantity":"2","unit":""},{"name":"courgettes","quantity":"2","unit":""},{"name":"red peppers","quantity":"2","unit":""},{"name":"red onion","quantity":"1","unit":""},{"name":"small sweet potato","quantity":"1","unit":"(about 200g)"},{"name":"olive oil","quantity":"4","unit":"tbsp"},{"name":"large garlic cloves","quantity":"6","unit":"","notes":"thinly sliced"},{"name":"fresh oregano","quantity":"small bunch","unit":"leaves from"},{"name":"unsalted cashews","quantity":"100g","unit":""},{"name":"soft sun-dried tomatoes","quantity":"50g","unit":"","notes":"roughly chopped"},{"name":"salt, black pepper and crushed dried chillies","quantity":"","unit":"all to taste"}]},{"section_title":"Assembly","items":[{"name":"Puff Pastry","quantity":"375g","unit":"ready-made all-butter or vegan"},{"name":"beaten egg","quantity":"","unit":"to glaze"}]}]', '["To make the filling, heat the oven to 220°C/425°F/gas 7. Trim or peel the vegetables, then cut into 2cm chunks and put into the roasting tin.","Spoon over the olive oil and toss everything so the oil lightly coats the chunks. Roast in the heated oven for 20 minutes. Carefully toss and turn the vegetables using a fish slice, then roast for another 20 minutes.","Remove the tin from the oven and add the garlic and oregano. Season with salt, pepper and chilli flakes and toss everything together gently. Return to the oven and roast for a further 12-20 minutes until the vegetables are tender.","Meanwhile, spread the cashews in a small baking dish or tin and toast in the oven for 5-7 minutes until golden. Set aside.","Remove the vegetables from the oven and stir in the toasted cashews and sun-dried tomatoes. Taste and add more seasoning. Leave to cool completely.","When ready to assemble, roll out the pastry on a lightly floured worktop to a 45x30cm rectangle. Cut the pastry into 2 rectangles, one 25x30cm (lid) and the other 20x30cm (base).","Roll up the smaller rectangle (base) and unroll it on to a lined baking sheet. Brush beaten egg over a 1.5cm border all round the edges.","Spoon the cold vegetable filling on to the central part of the pastry (leave the egg-glazed border exposed), mounding it up neatly in the middle.","Roll up the pastry lid and gently unroll and drape it over the top of the filling. Use your fingers to press and seal the edges. Mark the pastry border with the back of a fork, then roll or curl the edge inwards. Chill for 20 minutes.","Meanwhile, heat the oven to 220°C/425°F/gas 7. Brush the pastry lid with beaten egg to glaze, then cut 5 slits across the top. Bake for about 25 minutes until the pastry is rich golden brown and crisp. Serve hot."]', 'Pie, Vegetarian, Roast, Cashew', '4-6'),
(147, 'Spanish omelette', '[{"section_title":"Main","items":[{"name":"medium onion","quantity":"1","unit":"(optional)"},{"name":"olive oil","quantity":"300ml","unit":""},{"name":"Salt and pepper","quantity":"","unit":""},{"name":"waxy potatoes","quantity":"600g","unit":""},{"name":"medium eggs","quantity":"6","unit":"beaten"},{"name":"extra-virgin olive oil","quantity":"2","unit":"tbsp"}]}]', '["Peel and finely slicing the onion (if using).","Heat the 300ml olive oil in a large frying pan over a medium-low flame, then add the onion and a pinch of salt. Stir to coat, then cook gently for about 20 minutes, until very soft and limp.","Peel and thinly slice the potatoes (a mandoline is ideal). Rinse the potato slices in cold water, then pat them as dry as you can in a clean tea towel.","Add the potatoes to the onion pan (in batches if needed). Cook until the potatoes are soft and on the verge of falling apart.","Drain the contents of the pan, reserving the oil for later. Let the potatoes and onions cool a little.","Crack the eggs into a large bowl, beat well, season, then add the cooled onions and potatoes. Leave to stand for 10 minutes.","Put a smaller frying pan (about 22cm) on a medium heat and add the 2 tbsp extra-virgin olive oil. Once hot, add the egg and potato mixture.","Leave the tortilla to cook, undisturbed, until the edges begin to come away and it''s about two-thirds set.","Loosen around the edge with a spatula. Put a lipped plate on top of the pan and flip over. Slide the inverted tortilla back into the pan.","Carry on cooking until the tortilla is springy to the touch. Leave to cool to at least warm before serving."]', 'Omelette, Potato, Vegetarian, Tapas', '4 as a meal, 8 as tapas'),
(148, 'Crisps tortilla', '[{"section_title":"Main","items":[{"name":"extra virgin olive oil","quantity":"1","unit":"tbsp"},{"name":"onion or 1 shallot","quantity":"1/2","unit":"","notes":"finely sliced"},{"name":"large free range eggs","quantity":"6","unit":""},{"name":"salted crisps","quantity":"80g","unit":""},{"name":"salad leaves","quantity":"2","unit":"large handfuls (about 90g)"},{"name":"sherry or white wine vinegar","quantity":"1/2","unit":"tsp"},{"name":"chives (or dill or parsley)","quantity":"Small handful","unit":"","notes":"finely sliced"}]}]', '["Put ½ tbsp oil in a small, nonstick frying pan with the onion (or shallot) and a pinch of salt. Set over a medium heat and cook for 5 minutes until softened and lightly golden.","Meanwhile, in a mixing bowl, whisk the eggs. Once the onion is cooked, add to the eggs along with the crisps. Season and stir to combine, then let stand for 2 minutes to allow the crisps to soften a little.","Wipe out the pan and add another 1/2 tbsp oil. Set over a medium-high heat and, when the oil is shimmering, add the egg mixture.","Using a rubber spatula, move the mixture around the pan to evenly disperse and cook for 3-5 minutes, until mostly set but the top is still runny.","Carefully flip the tortilla onto a plate, so that the cooked side faces up. Slide the tortilla back into the pan, then cook for 3-5 minutes, without touching, until the other side is golden.","Dress the salad leaves with the remaining 1/2 tsp oil and the vinegar, season and toss through the herbs. Halve the tortilla and serve with the salad."]', 'Omelette, Vegetarian, Potato', '2'),
(149, 'Harissa & honey halloumi bites', '[{"section_title":"Main","items":[{"name":"halloumi","quantity":"2 x 250g","unit":"blocks"},{"name":"clear honey","quantity":"4","unit":"tbsp"},{"name":"rose harissa","quantity":"2","unit":"tbsp"},{"name":"olive oil","quantity":"2","unit":"tbsp"}]}]', '["Cut each halloumi block into bitesized chunks (2-3cm).","In a small bowl, mix together the honey and harissa.","Heat a large frying pan over a high heat, drizzle in the oil, then add the halloumi and fry until golden brown on all sides, turning frequently (5-6 minutes).","Pour the honey mixture over the halloumi, then immediately stir to coat to avoid burning. Bubble away, stirring constantly, for a couple of minutes.","Remove from the heat and serve straight away."]', 'Halloumi, Starter, Vegetarian, Gluten-free', '6-8'),
(150, 'A chunky vegetable soup', '[{"section_title":"Main","items":[{"name":"vegetable oil","quantity":"1-2","unit":"tbsp"},{"name":"onions","quantity":"2","unit":"","notes":"peeled and chopped small"},{"name":"garlic cloves","quantity":"2-3","unit":"","notes":"peeled and chopped"},{"name":"celery stick","quantity":"1","unit":"","notes":"chopped"},{"name":"mixed dried herbs","quantity":"1","unit":"tbsp","notes":"or 2 tbsp chopped fresh herbs"},{"name":"Salt and black pepper","quantity":"","unit":""},{"name":"mixed vegetables (carrots, sweet potato, leeks, potatoes)","quantity":"800g","unit":"","notes":"all cut into 2cm dice"},{"name":"chilli powder","quantity":"1 1/2","unit":"tsp","notes":"or 1 tsp hot chilli sauce"},{"name":"dried lentils, beans, and/or pulses","quantity":"100g","unit":"","notes":"soaked in 300ml cold water for 12 hours, then drained"},{"name":"chickpeas","quantity":"1 x 400g","unit":"tin, drained"},{"name":"chopped tomatoes, or passata","quantity":"1 x 400g","unit":"tin"},{"name":"vegetable stock","quantity":"800ml","unit":""},{"name":"frozen peas","quantity":"185g","unit":""}]}]', '["(Optional: Make stock from vegetable peelings and trimmings in 800ml boiling water in microwave for 10 mins).","In a large pan, heat the oil, then fry the onion and garlic on a low heat for 5-10 minutes, until they start to soften.","Stir in the celery and herbs, a hefty pinch each of salt and pepper, and cook for a few minutes.","Add all the diced mixed vegetables, turn the heat to high and fry, stirring regularly, until they start to catch and colour at the edges.","Add the chilli and the drained lentils and chickpeas, then stir in the tomatoes and stock.","Bring to a boil, turn down to a simmer, cover and cook for 40-50 minutes, until the vegetables are tender.","Taste and adjust the seasoning, if necessary, then stir through the peas until cooked, and serve in warmed bowls."]', 'Soup, Vegetarian, Vegan, Stew', '4-6'),
(151, 'Roast sweet potato & tomato soup', '[{"section_title":"Main","items":[{"name":"Evangeline Sweet Potatoes","quantity":"600g","unit":"pack, scrubbed"},{"name":"medium onion","quantity":"1","unit":"","notes":"cut into 6 wedges"},{"name":"cloves garlic","quantity":"4","unit":"","notes":"unpeeled and bashed"},{"name":"thyme","quantity":"8","unit":"sprigs"},{"name":"caster sugar","quantity":"1","unit":"tsp"},{"name":"extra virgin olive oil","quantity":"4","unit":"tbsp"},{"name":"cherry tomatoes","quantity":"400g","unit":"can"},{"name":"ham, chicken or vegetable stock","quantity":"500ml","unit":""},{"name":"sea salt flakes","quantity":"1","unit":"tsp"},{"name":"sage","quantity":"1/4 x 20g","unit":"pack, leaves picked"},{"name":"mixed seeds","quantity":"3","unit":"tbsp"}]}]', '["Preheat the oven to 200°C, gas mark 6. Cut the sweet potatoes into 4cm-thick discs (leaving the skin on).","Spread in 1 layer on a baking tray, dotting the onion wedges, garlic and thyme in the gaps. Sprinkle over the sugar and drizzle with 3 tbsp oil. Turn the vegetables to ensure they''re all coated, then roast for 35-40 minutes.","Transfer the roast vegetables to a large pan, discarding the papery bits of garlic and any woody pieces of thyme. Add the cherry tomatoes, stock and 500ml water. Bring to the boil, then simmer for 5 minutes.","Use a stick blender or upright blender to whizz to a silky soup. Season with the salt.","Heat the remaining 1 tbsp oil in a small pan over a medium heat, then fry the sage leaves until golden (2-3 minutes); transfer to a plate. Lower the heat slightly, then toast the seeds in the same pan for a few minutes.","Divide the soup among 6 bowls and top with the sage and seeds."]', 'Soup, Vegetarian, Sweet Potato, Roast', '6'),
(152, 'Pumpkin and rice soup', '[{"section_title":"Main","items":[{"name":"butter","quantity":"30g","unit":""},{"name":"olive oil","quantity":"3","unit":"tbsp"},{"name":"carrot","quantity":"1","unit":"","notes":"peeled and diced"},{"name":"onion","quantity":"1","unit":"","notes":"peeled and diced"},{"name":"celery stick","quantity":"1","unit":"","notes":"peeled and diced"},{"name":"salt","quantity":"1","unit":"pinch"},{"name":"pumpkin or butternut flesh","quantity":"400g","unit":"peeled, small-diced"},{"name":"light vegetable or chicken broth, or water","quantity":"1.2","unit":"litres"},{"name":"rice (arborio or vialone nano)","quantity":"180g","unit":""},{"name":"grated parmesan","quantity":"2","unit":"tbsp","notes":"plus extra to serve"},{"name":"pepper","quantity":"","unit":""},{"name":"red chilli flakes","quantity":"","unit":"","notes":"to serve (optional)"}]}]', '["In a large, heavy-based pan, heat the butter and olive oil. Add the carrot, onion, celery, and a pinch of salt, frying gently until the vegetables are starting to turn translucent.","Add 400g peeled, small-diced pumpkin or butternut flesh and stir for a minute or two, so that each piece is well coated.","Add 1.2 litres of light vegetable or chicken broth, or water, bring to an almost-boil, then reduce to a simmer for 15 minutes.","Add 180g rice and simmer, stirring every now and then, for 17-20 minutes, until the rice is tender, adding more water if need be.","Taste and add two tablespoons of grated parmesan, salt and pepper, and stir well.","Serve, passing round extra grated parmesan, olive oil and red chilli flakes for those who want them."]', 'Soup, Vegetarian, Pumpkin, Rice', '4'),
(153, 'Caramelized onion and chilli ramen', '[{"section_title":"Main","items":[{"name":"rapeseed oil","quantity":"5","unit":"tbsp"},{"name":"large brown onions","quantity":"3","unit":"(500g), finely sliced"},{"name":"cloves of garlic","quantity":"3","unit":"","notes":"finely sliced"},{"name":"salt","quantity":"1 1/2","unit":"tsp"},{"name":"bird''s-eye chilli","quantity":"1","unit":"","notes":"finely sliced"},{"name":"vegetable stock","quantity":"1 1/2","unit":"litres"},{"name":"cooking sake","quantity":"2","unit":"tbsp","notes":"or Chinese rice wine/dry sherry"},{"name":"light soy sauce","quantity":"1 1/2","unit":"tbsp"},{"name":"brown rice miso","quantity":"1","unit":"tbsp"},{"name":"ramen noodles","quantity":"200g","unit":""},{"name":"choi sum","quantity":"200g","unit":"","notes":"cut into 6cm pieces"},{"name":"soy eggs or soft-boiled eggs","quantity":"4","unit":"","notes":"(optional)"},{"name":"chilli oil","quantity":"","unit":"","notes":"to serve (optional)"}]}]', '["In a large, heavy-bottomed saucepan, warm 5 tablespoons of oil over a medium heat. Add the onions, garlic and salt, stir to coat in the oil and cook for 8 to 10 minutes, until the onions become translucent.","Reduce the heat to its lowest setting and continue to cook for 30-40 minutes, stirring every 5 minutes. The onions will gradually caramelize and colour, eventually breaking down to form a soft, sweet paste.","Add the bird''s-eye chilli and stock, bring to boil, then reduce the heat to a simmer and add the sake, soy sauce and brown rice miso, stirring well to combine. Check the seasoning.","Cook your noodles according to the packet instructions. Refresh in cold water and stir in a little oil to keep them from sticking.","Finally, bring the broth back to the boil, add the choi sum and cook for 1 to 2 minutes, until tender.","To serve, divide your noodles between four bowls and ladle the broth and greens over the noodles. If you''re serving the eggs, halve and pop on top, and serve with some chilli oil if you like."]', 'Ramen, Soup, Vegetarian, Vegan', '4'),
(154, 'Roasted tomato & squash soup', '[{"section_title":"Main","items":[{"name":"Classic Vine Tomatoes","quantity":"2 x 450g","unit":"packs, halved"},{"name":"frozen Cooks'' Ingredients Butternut Squash chunks","quantity":"200g","unit":""},{"name":"onions","quantity":"3","unit":"","notes":"roughly chopped"},{"name":"cloves garlic","quantity":"5","unit":"","notes":"peeled"},{"name":"butter beans","quantity":"400g","unit":"can, drained and rinsed"},{"name":"olive oil","quantity":"3","unit":"tbsp"},{"name":"vegetable stock","quantity":"1","unit":"litre, heated"},{"name":"red wine vinegar","quantity":"1","unit":"tbsp"},{"name":"caster sugar","quantity":"1/2","unit":"tsp"},{"name":"vegan basil pesto","quantity":"4-5","unit":"tsp"}]}]', '["Preheat the oven to 200°C, gas mark 6. Arrange the halved tomatoes, butternut squash, onions, garlic and 3/4 of the butter beans in 1-2 large roasting tin(s). Toss with 2 tbsp oil and season. Roast for 40 minutes, stirring halfway through.","Meanwhile, on a separate small tray, toss the reserved butter beans with the remaining 1 tbsp oil and season. Roast for 15-20 minutes until golden and crisp.","When the vegetables are ready, remove from the oven and set aside to cool for 5 minutes.","Blend the roasted vegetables with the hot stock, vinegar and sugar in a saucepan with a stick blender (or whizz in batches) until smooth. Season and add a little water to loosen, if needed.","Reheat the soup and serve in bowls topped with the crispy butter beans and pesto."]', 'Soup, Vegetarian, Vegan, Roast, Squash', '4-5'),
(155, 'Tomato and Lentil Soup', '[{"section_title":"Main","items":[{"name":"oil","quantity":"1","unit":"tablespoon"},{"name":"Marmite","quantity":"1/2","unit":"teaspoon"},{"name":"medium onion","quantity":"1","unit":"","notes":"chopped"},{"name":"medium carrot","quantity":"1","unit":"","notes":"chopped"},{"name":"clove garlic","quantity":"1","unit":"","notes":"chopped"},{"name":"red lentils","quantity":"1/4","unit":"mug"},{"name":"tomatoes","quantity":"400g","unit":"can"},{"name":"water","quantity":"2","unit":"mugs"},{"name":"vegetable stock cube","quantity":"1","unit":"","notes":"crumbled in"},{"name":"bread","quantity":"","unit":"","notes":"to serve"}]}]', '["Heat the oil in a saucepan and add the onion, carrot and garlic. Cook until the onion is soft.","Add the lentils, tomatoes, Marmite, stock cube and water. Bring to the boil, then turn down and simmer for 20 minutes until the lentils are tender.","Once the soup is cooked, season well with salt and freshly ground black pepper. Use a hand-held blender to blitz the soup. Serve with bread."]', 'Soup, Vegetarian, Vegan, Lentil', '4'),
(156, 'Roasted butternut squash soup', '[{"section_title":"Main","items":[{"name":"butternut squash","quantity":"1.5kg","unit":"peeled and deseeded, cut into 3cm cubes"},{"name":"large onion","quantity":"1","unit":"","notes":"roughly chopped"},{"name":"medium carrots","quantity":"2","unit":"","notes":"peeled and chopped"},{"name":"red pepper","quantity":"1","unit":"","notes":"deseeded and cut into cubes"},{"name":"olive oil","quantity":"4","unit":"tbsp"},{"name":"clear honey","quantity":"1","unit":"tbsp"},{"name":"fresh root ginger","quantity":"5cm/2in","unit":"piece, peeled and chopped"},{"name":"vegetable stock","quantity":"1.5","unit":"litres"},{"name":"salt and freshly ground black pepper","quantity":"","unit":""}]}]', '["Preheat the oven to 200C/180C Fan/Gas 6.","Tip the prepared squash into a large, resealable freezer bag with the onion, carrots and red pepper. Add half the oil and salt and pepper and toss everything together until the vegetables are evenly coated.","Tip into a large roasting tin and spread out to form a single layer. Roast in the oven for 40-45 minutes, or until tender and tinged brown. Drizzle over the honey 5 minutes before the end of cooking.","Place a large, deep-sided saucepan over a medium heat, add the remaining oil and, when it is hot, add the ginger and fry for a minute.","Pour in the stock and bring to the boil, then stir in the roasted vegetables and add salt and pepper.","Remove the saucepan from the heat and, using a hand blender, blend the mixture until smooth. Return to the heat to warm through and serve hot with crusty bread."]', 'Soup, Vegetarian, Roast, Squash', '8'),
(157, 'Minestrone', '[{"section_title":"Main","items":[{"name":"red onions","quantity":"2","unit":""},{"name":"carrots","quantity":"2","unit":""},{"name":"celery sticks","quantity":"2","unit":""},{"name":"butter or pancetta","quantity":"40g","unit":""},{"name":"extra virgin olive oil","quantity":"4","unit":"tbsp"},{"name":"Salt and black pepper","quantity":"","unit":""},{"name":"potatoes","quantity":"200g","unit":"peeled and diced"},{"name":"other vegetables (fennel, peas, etc)","quantity":"300g","unit":""},{"name":"savoy cabbage or kale","quantity":"200g","unit":"shredded"},{"name":"tinned plum or fresh tomatoes","quantity":"120g","unit":"(around half a tin)"},{"name":"parmesan rind","quantity":"A large","unit":""},{"name":"cooked cannellini beans","quantity":"400g","unit":""},{"name":"water","quantity":"2","unit":"litres"},{"name":"short pasta or rice","quantity":"150g","unit":"(for first serving)"},{"name":"grated parmesan","quantity":"2","unit":"tbsp"},{"nameBoolean":"true","title":"toast","quantity":"4","unit":"slices","notes":"(for second serving)"}]}]', '["Peel and dice the onion, carrot and celery. In a large, heavy-based pan, over a medium-low heat, gently fry these in the olive oil and butter (or pancetta) with a pinch of salt, stirring every now and then for about 8 minutes, or until soft and fragrant.","Meanwhile, peel and dice the potatoes, then add them to the pan, stir and cook for 5 minutes.","Chop the other vegetables, shred the cabbage/kale, add all these to the pan and cook for another 5 minutes.","Add the tinned tomatoes and parmesan rind, stir, then add 2 litres of water, cover and leave to simmer gently for 1 1/2 hours.","Add the beans. Stir and cook for another 30 minutes. If you find the minestrone is looking a little too thick, or dry, add a little more water. Once cooked, fish out the rind and season with salt and pepper.","To serve, two ways. On the first day, serve half the soup with some short pasta or rice cooked separately until al dente; maybe swirl in some grated parmesan. The second day, serve it over toast zig-zagged with olive oil and sprinkled with cheese."]', 'Soup, Vegetarian, Minestrone', '8'),
(158, 'Mediterranean Vegetable & Tomato Soup', '[{"section_title":"Main","items":[{"name":"olive oil","quantity":"1","unit":"tablespoon"},{"name":"small onion","quantity":"1","unit":"","notes":"finely chopped"},{"name":"clove garlic","quantity":"1","unit":"","notes":"crushed"},{"name":"red pepper","quantity":"half a","unit":"","notes":"diced"},{"name":"yellow pepper","quantity":"half a","unit":"","notes":"diced"},{"name":"courgettes","quantity":"2","unit":"","notes":"diced"},{"name":"vegetable stock","quantity":"1","unit":"litre"},{"name":"sweet smoked paprika","quantity":"1","unit":"teaspoon"},{"name":"fresh rosemary","quantity":"1","unit":"teaspoon","notes":"finely chopped"},{"name":"balsamic vinegar","quantity":"1","unit":"teaspoon"},{"name":"chopped tomatoes","quantity":"1 x 400g","unit":"tin"},{"name":"sun-dried tomato paste","quantity":"1","unit":"tablespoon"},{"name":"fresh parsley","quantity":"1","unit":"teaspoon","notes":"finely chopped"}]}]', '["Heat the oil in a saucepan, add the onion and garlic, then cook gently for 5 minutes, without browning.","Add the pepper, courgettes, paprika and rosemary, then cook for 3 minutes, stirring all the while.","Add the balsamic vinegar, simmer for 2 minutes, then add the chopped tomatoes and stock.","Bring to the boil, then cover and simmer for 15 minutes or until the vegetables are tender.","Stir in the sun-dried tomato paste and parsley, then season to taste and serve."]', 'Soup, Vegetarian, Vegan, Mediterranean', '4'),
(159, 'Red Lentil, Cumin & Coriander Soup', '[{"section_title":"Main","items":[{"name":"extra virgin olive oil","quantity":"2","unit":"tablespoons"},{"name":"medium onion","quantity":"1","unit":"","notes":"finely chopped"},{"name":"ground coriander","quantity":"1","unit":"level teaspoon"},{"name":"ground tumeric","quantity":"1","unit":"level teaspoon"},{"name":"ground cumin","quantity":"1","unit":"level teaspoon"},{"name":"ground cloves","quantity":"a pinch","unit":""},{"name":"red lentils","quantity":"350g","unit":"washed"},{"name":"vegetable stock","quantity":"1.2","unit":"litres"},{"name":"chopped tomatoes","quantity":"1 x 400g","unit":"tin"},{"name":"fresh coriander leaves","quantity":"20g","unit":""}]},{"section_title":"Garnish","items":[{"name":"extra virgin olive oil","quantity":"1","unit":"tablespoon"},{"name":"large fresh green chilli","quantity":"1","unit":"","notes":"chopped"},{"name":"fresh coriander leaves","quantity":"2","unit":"tablespoons"}]}]', '["Heat the oil in a saucepan, add the onion, then cover and cook gently for 5 minutes, without browning. Add the dried spices, then cook, stirring frequently, for a further 5 minutes.","Add the lentils and stock, cover, then bring to the boil. Simmer gently for 20 minutes until the lentils are tender.","Add the tomatoes, then simmer for 10 minutes. Blend with the 20g fresh coriander leaves until smooth. Season to taste.","For the garnish: heat the 1 tbsp oil in a frying pan, then fry the green chilli for 2 minutes.","Serve the soup garnished with the chilli and fresh coriander leaves."]', 'Soup, Vegetarian, Vegan, Lentil', '4-6'),
(160, 'Sweet Potato & Orange Soup', '[{"section_title":"Main","items":[{"name":"butter","quantity":"20g","unit":""},{"name":"large onion","quantity":"1/2","unit":"","notes":"finely chopped"},{"name":"Sweet potatoes","quantity":"500g","unit":"peeled (375g roughly chopped, 125g diced)"},{"name":"potatoes","quantity":"200g","unit":"peeled and roughly chopped"},{"name":"freshly squeezed orange juice","quantity":"2","unit":"tablespoons"},{"name":"vegetable stock","quantity":"700ml","unit":""},{"name":"ground coriander","quantity":"half a","unit":"teaspoon"},{"name":"milk","quantity":"150ml","unit":""}]},{"section_title":"Garnish","items":[{"name":"sunflower oil","quantity":"1","unit":"tablespoon"},{"name":"bacon","quantity":"3","unit":"rashers"},{"name":"crème fraîche","quantity":"150ml","unit":""}]}]', '["Melt the butter in a saucepan, add the onion, cover, then cook gently until soft, without browning.","Add the roughly chopped sweet potatoes, potatoes, orange juice, vegetable stock and ground coriander.","Cover, bring to the boil, then simmer for 30 minutes until the vegetables are tender. Add the milk, then blend until smooth. Season to taste.","Return to a clean pan, stir in the diced sweet potato, then cover and bring to the boil. Simmer for 15 minutes until the sweet potatoes are tender.","Meanwhile, heat the oil in a frying pan, fry the bacon until crisp, then drain on kitchen paper.","Serve the soup garnished with tablespoons of crème fraîche and topped with crispy bacon."]', 'Soup, Vegetarian, Sweet Potato', '4');